	if err != nil {
		log.Printf("启动DAG失败: TraceID=%s, err=%v", params.TraceID, err)
		// 发送告警通知
		msg := "[开始审核DAG触发失败]\n" +
			"DAG名称: " + global.TaskComeNewAuditStartTPDagName + "\n" +
			"TraceID: " + params.TraceID + "\n" +
			"算子: " + "启动开始审核DAG" + "\n" +
			"错误: " + err.Error() + "\n" +
			"时间: " + time.Now().Format("2006-01-02 15:04:05")
		utils.SendMsgToHi(msg, global.MenuAlarmAtUsers)
		return err
	}
	return nil
}

// saveToAuditResultTable 将审核数据保存到tp_t_audit_result表
func (c *MEGAccessConsumer) saveToAuditResultTable(ctx context.Context, params *global.TaskComeRequest) error {
	// 构建审核结果记录
	auditResult := &tpdb.AuditResult{
		TraceID:   params.TraceID,
		SendExtra: string(params.SendExtra), // 初始为空，后续更新
		StoreID:   params.StoreID,
		PoiName:   params.PoiName,
		Address:   params.Address,
		City:      params.City,
		AuditTime: int(params.CreateTime),
	}

	// 创建审核记录
	if err := auditResult.Create(); err != nil {
		return fmt.Errorf("创建审核记录失败: %v", err)
	}

	log.Printf("成功写入审核结果表(TraceID=%s, StoreID=%d)",
		params.TraceID, params.StoreID)
	return nil
}

func (c *MEGAccessConsumer) StartAuditDag(ctx context.Context, req *global.TaskComeRequest) error {
	// 准备审核参数
	params, err := c.prepareAuditParams(req)
	if err != nil {
		return err
	}

	// 将数据写入tp_t_audit_result表
	if err := c.saveToAuditResultTable(ctx, params); err != nil {
		log.Printf("写入审核结果表失败(TraceID=%s): %v", params.TraceID, err)
		// 继续执行，不因为写入失败而中断整体流程
	}

	// 创建并启动 DAG
	return c.createDAG(ctx, params)
}

